"use strict";(self.webpackChunkizakharau_blog_docusaurus=self.webpackChunkizakharau_blog_docusaurus||[]).push([[3227],{6786:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"Replacing Legacy","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Definition, Reasons, Characteristics","href":"/essays/replacing-legacy/replacing-legacy-1","docId":"replacing-legacy/replacing-legacy-1","unlisted":false},{"type":"link","label":"Archeology, Politics, Red Flags","href":"/essays/replacing-legacy/replacing-legacy-2","docId":"replacing-legacy/replacing-legacy-2","unlisted":false},{"type":"link","label":"Conversion & Data Mapping","href":"/essays/replacing-legacy/replacing-legacy-3","docId":"replacing-legacy/replacing-legacy-3","unlisted":false},{"type":"link","label":"Business Logic Burden","href":"/essays/replacing-legacy/replacing-legacy-4","docId":"replacing-legacy/replacing-legacy-4","unlisted":false},{"type":"link","label":"Cloud, SaaS Legacy, and AI","href":"/essays/replacing-legacy/replacing-legacy-5","docId":"replacing-legacy/replacing-legacy-5","unlisted":false}],"href":"/essays/replacing-legacy/"},{"type":"category","label":"Requirements & API","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Glossary","href":"/essays/requirements-api/1-glossary","docId":"requirements-api/glossary","unlisted":false},{"type":"link","label":"Definitions","href":"/essays/requirements-api/2-definitions","docId":"requirements-api/definitions","unlisted":false},{"type":"link","label":"Analysis","href":"/essays/requirements-api/3-analysis","docId":"requirements-api/analysis","unlisted":false},{"type":"link","label":"Design","href":"/essays/requirements-api/4-design","docId":"requirements-api/design","unlisted":false},{"type":"link","label":"Interface Definition Languages (IDL)","href":"/essays/requirements-api/5-idl","docId":"requirements-api/idl","unlisted":false},{"type":"link","label":"Workflows","href":"/essays/requirements-api/6-workflows","docId":"requirements-api/workflows","unlisted":false},{"type":"link","label":"[Bonus] API Design Series Overview","href":"/essays/requirements-api/api-design","docId":"requirements-api/api-design","unlisted":false}],"href":"/essays/requirements-api/"}]},"docs":{"replacing-legacy/index":{"id":"replacing-legacy/index","title":"Replacing Legacy","description":"Replacing Legacy Series - provides a comprehensive exploration of the challenges and considerations involved in modernizing or replacing outdated computer systems. This series draws on the author\'s experience, including a project involving a three-decade-old COBOL monolith, and offers insights for business analysts and other professionals involved in the challenging but necessary task of replacing legacy systems.","sidebar":"tutorialSidebar"},"replacing-legacy/replacing-legacy-1":{"id":"replacing-legacy/replacing-legacy-1","title":"Definition, Reasons, Characteristics","description":"Let\'s start with a definition of \\"Legacy\\":","sidebar":"tutorialSidebar"},"replacing-legacy/replacing-legacy-2":{"id":"replacing-legacy/replacing-legacy-2","title":"Archeology, Politics, Red Flags","description":"In this part, we cover one of the approaches for modernization and possible caveats.","sidebar":"tutorialSidebar"},"replacing-legacy/replacing-legacy-3":{"id":"replacing-legacy/replacing-legacy-3","title":"Conversion & Data Mapping","description":"Previously, I mentioned an approach of \\"wrapping\\" a legacy system by providing a modern API layer as an abstraction to separate the Legacy from their clients. And migrate them to new APIs with the updated data format/new models. After that, you can proceed with the decomposition, not bothering the clients again.","sidebar":"tutorialSidebar"},"replacing-legacy/replacing-legacy-4":{"id":"replacing-legacy/replacing-legacy-4","title":"Business Logic Burden","description":"In the previous chapters, we focused on a gap we must cover for transitioning from a legacy to a new model definition. The business logic layer is the next challenge to address.","sidebar":"tutorialSidebar"},"replacing-legacy/replacing-legacy-5":{"id":"replacing-legacy/replacing-legacy-5","title":"Cloud, SaaS Legacy, and AI","description":"Here, we reflect on the reasoning behind the past, current, and future trends: Cloud deployments, SaaS (Software-as-a-Service), and AI (Artificial Intelligence). The first two can\u2019t be considered trends anymore. It has been the reality for more than a decade. AI is more speculative; knowing it impacts the industry, we still need to find out to what extent that will be.","sidebar":"tutorialSidebar"},"requirements-api/analysis":{"id":"requirements-api/analysis","title":"Analysis","description":"With this chapter, we first will understand why we need requirements for API and their place in the requirements classification frameworks. Then, we review the requirements engineering process and specific aspects you need to consider.","sidebar":"tutorialSidebar"},"requirements-api/api-design":{"id":"requirements-api/api-design","title":"[Bonus] API Design Series Overview","description":"In 2022 I started exploring the API design-first approach and dedicated to this topic a series of articles on Linkedin (1, 2, 3, 4). I have revised the entire material and published the enhanced version on my blog.","sidebar":"tutorialSidebar"},"requirements-api/definitions":{"id":"requirements-api/definitions","title":"Definitions","description":"What is API?","sidebar":"tutorialSidebar"},"requirements-api/design":{"id":"requirements-api/design","title":"Design","description":"This chapter explores the structure and API design specifics of HTTP API and its definition with the OpenAPI specification. Then, we distinguish a traditional code-first, design-first, and fresh-new AI approach to API development.","sidebar":"tutorialSidebar"},"requirements-api/glossary":{"id":"requirements-api/glossary","title":"Glossary","description":"| Term                     | Definition                                                                                                                                                                                     |","sidebar":"tutorialSidebar"},"requirements-api/idl":{"id":"requirements-api/idl","title":"Interface Definition Languages (IDL)","description":"In the previous chapter, we examined the OpenAPI specification (OAS) as a tool for designing a RESTful API request for a Web application. In this chapter, we will explore several languages that help formalize the API definition and automate development.","sidebar":"tutorialSidebar"},"requirements-api/index":{"id":"requirements-api/index","title":"Requirements & API","description":"Requirements & API Series is a deep dive into the intersection of product management, requirements engineering, and API design. This series explores best practices for defining, documenting, and managing API requirements, covering topics such as workflows, OpenAPI specifications, UML diagrams, and API governance. Whether you\'re a product manager, developer, or architect, these articles will help you navigate the complexities of API-first product development.","sidebar":"tutorialSidebar"},"requirements-api/workflows":{"id":"requirements-api/workflows","title":"Workflows","description":"Most IDLs define a set of API endpoints related to a particular domain, entity, or service but do not specify in which workflows (or business processes) those API are utilized. This causes specific issues in end-to-end scenarios involving different pieces from one or another system.","sidebar":"tutorialSidebar"}}}}')}}]);